#include "ccu6_generic.h"

/**********************************************************************************************************************
 * API IMPLEMENTATION
 **********************************************************************************************************************/

/* Get the CCU6_GENERIC APP version. */
ACS_APP_VERSION_t CCU6_GENERIC_GetAppVersion()
{
  ACS_APP_VERSION_t version;

  version.major = CCU6_GENERIC_MAJOR_VERSION;
  version.minor = CCU6_GENERIC_MINOR_VERSION;
  version.patch = CCU6_GENERIC_PATCH_VERSION;

  return version;
}

/* Function to initialize the CCU6 MOSEL register. */
CCU6_GENERIC_STATUS_t CCU6_GENERIC_Init(CCU6_GENERIC_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));

  if (handle->app_is_initialized == FALSE)
  {
    /* Enable CCU60 module to allow access to MOSEL register */
    IfxCcu6_enableModule(&MODULE_CCU60);

    /* Initialize the CCU6 MOSEL register with the decided value */
    IfxCcu6_connectTrigger(handle->app_config->ccu6_top_4_trig0sel, IfxCcu6_TrigOut_0, handle->app_config->trig0sel);
    IfxCcu6_connectTrigger(handle->app_config->ccu6_top_4_trig1sel, IfxCcu6_TrigOut_1, handle->app_config->trig1sel);
    IfxCcu6_connectTrigger(handle->app_config->ccu6_top_4_trig2sel, IfxCcu6_TrigOut_2, handle->app_config->trig2sel);

    handle->app_is_initialized = TRUE;
  }

  return CCU6_GENERIC_STATUS_SUCCESS;
}

